#!/bin/sh
# bench.sh: functional bench of the gateway image, without hardware (amd64 or arm64).
#
# Builds the gateway image (Dockerfile), then runs it against a simulated Quectel EC25
# (tests/fake_ec25.py over tests/fake_eg06.py): calls with RING and +QIND "ccinfo" and AT+CLCC
# polling, SMS in PDU mode and USSD. SIP side: a softphone (tests/sip_client.py) and a SIP server in
# "register" and "ip" modes (tests/fake_registrar.py), on the loopback.
# The Asterisk configuration is the one generated by gw-config, with voice over a serial port
# (the bench has no sound card). See tests/bench-inside.sh.
#
#   sh tests/bench.sh        results in out/bench/ (AT log, Asterisk console)
# Exit code: number of failed checks.
set -eu
cd "$(dirname "$0")/.."
REPO=$(pwd -W 2>/dev/null || pwd)   # Git Bash on Windows: Docker needs a Windows path
export MSYS_NO_PATHCONV=1
IMAGE=${IMAGE:-pi-ec25-gsm-sip-gateway:bench}
docker build -q -t "$IMAGE" . >/dev/null
docker build -q --build-arg IMAGE="$IMAGE" -f tests/Dockerfile.bench -t "$IMAGE-tools" tests >/dev/null
mkdir -p out/bench && rm -f out/bench/*
docker run --rm -v "$REPO/tests:/t:ro" -v "$REPO/out/bench:/res" --entrypoint sh "$IMAGE-tools" /t/bench-inside.sh
